css_equivalente:
/* =============================================================================
   SMSMais — CSS puro equivalente ao painel (sem Tailwind)
   Reproduz: shell (sidebar + topbar + conteudo), cabecalho de pagina, botoes,
   tabela de listagem, card, KPI, chip/badge, input/select/campo, abas, paginacao.

   TROCA DE MARCA (whitelabel, ADR-0043): mude SO o bloco "MARCA" abaixo.
   A escala 50..950 e derivada mecanicamente da cor 600 misturando com branco
   (passos claros) e com preto (passos escuros), com estes fatores:
     50:-0.95  100:-0.89  200:-0.76  300:-0.58  400:-0.35  500:-0.17
     600: 0    700: 0.16  800: 0.33  900: 0.46  950: 0.70
   (negativo = mistura com #fff; positivo = mistura com #000)
   Marica (producao) usa 600 = #C8102E. Os valores abaixo ja estao derivados
   para um azul institucional (#00529B) — substitua pelo azul oficial de Niteroi
   e recalcule os 11 passos com os fatores acima.
   ============================================================================= */

:root {
  /* ---------- MARCA (o unico bloco que muda por municipio) ---------- */
  --p-50:  #F2F6FA;
  --p-100: #E3ECF4;
  --p-200: #C2D5E7;
  --p-300: #94B6D5;
  --p-400: #598FBE;
  --p-500: #2B6FAC;
  --p-600: #00529B;   /* cor "cheia": botao, barra ativa, destaque */
  --p-700: #004582;
  --p-800: #003768;
  --p-900: #002C54;
  --p-950: #00192E;

  --marca-primaria:   var(--p-600);
  --marca-secundaria: var(--p-700);
  /* Gradiente do menu lateral e do botao primario: 145deg, 700 -> 600 -> 950 */
  --marca-grad-inicio: var(--p-700);
  --marca-grad-meio:   var(--p-600);
  --marca-grad-fim:    var(--p-950);
  --marca-gradiente: linear-gradient(145deg,
      var(--marca-grad-inicio) 0%, var(--marca-grad-meio) 55%, var(--marca-grad-fim) 100%);

  /* "Acento" das telas de Ouvidoria. No codigo real sao vermelhos fixos do
     Tailwind (red-600 #dc2626 / red-700 #b91c1c) em: icone do <h1>, aba ativa,
     pagina atual da paginacao e barras do grafico. Aqui ficam parametrizados
     para acompanhar a marca. */
  --acento:        var(--p-600);
  --acento-escuro: var(--p-700);

  /* ---------- NEUTROS ----------
     Atencao: o "gray" do painel e a escala ZINC (tailwind.config sobrescreve).
     O "slate" e o slate padrao. Os dois convivem: shell/tabela usam zinc,
     as telas de Ouvidoria usam slate. */
  --g-50:  #fafafa;  --g-100: #f4f4f5;  --g-200: #e4e4e7;  --g-300: #d4d4d8;
  --g-400: #a1a1aa;  --g-500: #71717a;  --g-600: #52525b;  --g-700: #3f3f46;
  --g-800: #27272a;  --g-900: #18181b;

  --s-50:  #f8fafc;  --s-100: #f1f5f9;  --s-200: #e2e8f0;  --s-300: #cbd5e1;
  --s-400: #94a3b8;  --s-500: #64748b;  --s-600: #475569;  --s-700: #334155;
  --s-800: #1e293b;  --s-900: #0f172a;

  --sucesso: #10b981;  --sucesso-600: #059669;
  --aviso:   #f59e0b;  --aviso-600:   #d97706;
  --erro:    #ef4444;  --erro-600:    #dc2626;

  /* ---------- SUPERFICIES ---------- */
  --fundo-pagina: #f9fafb;
  --superficie:   #ffffff;
  --texto:        #111827;
  --texto-suave:  #52525b;
  --borda:        #e4e4e7;

  /* ---------- TIPOGRAFIA ---------- */
  --fonte: Inter, system-ui, -apple-system, "Segoe UI", sans-serif;
  --peso-titulo: 700;
  --peso-corpo:  400;

  /* ---------- RAIOS ---------- */
  --raio-sm: 0.5rem;    /*  8px */
  --raio-md: 0.75rem;   /* 12px — botoes e inputs */
  --raio-lg: 1rem;      /* 16px — .card global */
  --raio-xl: 0.75rem;   /* 12px — cards das telas de Ouvidoria (rounded-xl) */
  --raio-btn-peq: 0.375rem; /* 6px — itens de menu, paginacao, botoes-icone */

  /* ---------- SOMBRAS ---------- */
  --sombra-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --sombra-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --sombra-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --sombra-marca:    0 4px 14px 0 rgb(0 0 0 / 0.30);
  --sombra-marca-lg: 0 10px 40px 0 rgb(0 0 0 / 0.35);

  /* ---------- MEDIDAS DO SHELL ---------- */
  --sidebar-larg: 18rem;            /* 288px expandida */
  --sidebar-larg-compacta: 5rem;    /*  80px recolhida */
  --topbar-alt: 4rem;               /*  64px */
  --conteudo-max: 80rem;            /* 1280px (max-w-7xl) */
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--fundo-pagina);
  color: var(--texto);
  font-family: var(--fonte);
  font-weight: var(--peso-corpo);
  -webkit-font-smoothing: antialiased;
}

h1 { font-size: 1.875rem; font-weight: 700; letter-spacing: -0.025em; margin: 0; }
h2 { font-size: 1.5rem;   font-weight: 600; letter-spacing: -0.025em; margin: 0; }
h3 { font-size: 1.25rem;  font-weight: 600; letter-spacing: -0.025em; margin: 0; }
h4 { font-size: 1.125rem; font-weight: 600; margin: 0; }

/* Barra de rolagem do painel */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: var(--g-100); }
::-webkit-scrollbar-thumb { background: var(--g-300); border-radius: 9999px; }
::-webkit-scrollbar-thumb:hover { background: var(--g-400); }

/* =========================================================================
   1. SHELL — sidebar fixa a esquerda + topbar branca + area de conteudo
   ========================================================================= */

.app { min-height: 100vh; background: var(--g-50); }

.sidebar {
  position: fixed; inset-block: 0; left: 0; z-index: 50;
  width: var(--sidebar-larg);
  display: flex; flex-direction: column;
  overflow-y: auto;
  background: var(--marca-gradiente);
  box-shadow: var(--sombra-marca-lg);
  transition: width .3s ease;
}
.sidebar--compacta { width: var(--sidebar-larg-compacta); }

/* Faixa branca do logo, no topo da sidebar */
.sidebar__marca {
  position: relative;
  display: flex; align-items: center; justify-content: center;
  padding: 1.25rem 0.75rem;
  background: #ffffff;
  border-bottom: 1px solid rgb(255 255 255 / 0.10);
}
.sidebar__marca img { height: 3.5rem; width: auto; max-width: 220px; object-fit: contain; }
/* Botao recolher/expandir, no canto superior direito da faixa branca */
.sidebar__toggle {
  position: absolute; top: .5rem; right: .5rem;
  padding: .375rem; border: 0; background: transparent; cursor: pointer;
  border-radius: var(--raio-btn-peq); color: var(--g-500); line-height: 0;
}
.sidebar__toggle:hover { background: var(--g-100); color: var(--g-900); }

/* Bloco do usuario logado */
.sidebar__usuario {
  display: flex; align-items: center; gap: .75rem;
  padding: 1rem;
  background: rgb(255 255 255 / 0.10);
}
.sidebar__usuario-nome  { font-size: .875rem; font-weight: 500; color: #fff; }
.sidebar__usuario-email { font-size: .75rem; color: rgb(255 255 255 / 0.70); }

.avatar {
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; overflow: hidden; border-radius: 9999px;
  width: 2.5rem; height: 2.5rem;
  font-size: .875rem; font-weight: 600; color: #fff;
  background-image: var(--marca-gradiente);
  border: 2px solid var(--marca-primaria);
}
.avatar--sm { width: 2rem; height: 2rem; }

/* Navegacao */
.sidebar__nav { flex: 1; padding: 1rem .75rem; display: flex; flex-direction: column; gap: .375rem; }

.menu-item {
  position: relative;
  display: flex; align-items: center; gap: .75rem;
  width: 100%;
  padding: .625rem .75rem;
  border: 0; background: transparent; cursor: pointer;
  border-radius: var(--raio-btn-peq);
  font-size: .875rem; font-weight: 500; text-align: left; text-decoration: none;
  color: rgb(255 255 255 / 0.90);
  transition: all .2s;
}
.menu-item:hover { background: rgb(255 255 255 / 0.10); }
.menu-item svg { width: 1.25rem; height: 1.25rem; flex-shrink: 0; }
/* Item / secao ativa: pilula branca com o texto na cor da marca */
.menu-item--ativo { background: #ffffff; color: var(--p-700); box-shadow: var(--sombra-md); }
/* Indentacao por nivel */
.menu-item--n1 { padding-left: 2.25rem; }  /* sub-item de secao */
.menu-item--n2 { padding-left: 3.5rem;  }  /* 3o nivel */
.menu-item__chevron { margin-left: auto; width: 1rem; height: 1rem; transition: transform .2s; }
.menu-item__chevron--fechado { transform: rotate(-90deg); }

/* Contador circular do menu (fundo branco, numero na cor da marca) */
.contador {
  display: inline-flex; align-items: center; justify-content: center;
  height: 1rem; min-width: 1rem; padding: 0 .25rem; margin-left: auto;
  border-radius: 9999px;
  font-size: 10px; font-weight: 700; line-height: 1;
  background: #ffffff; color: var(--acento-escuro);
  box-shadow: inset 0 0 0 1px var(--p-200);
}
.contador--vermelho { background: var(--erro); color: #fff; box-shadow: none; }

.sidebar__rodape {
  padding: 1rem .75rem;
  border-top: 1px solid rgb(255 255 255 / 0.15);
}

/* Topbar */
.topbar {
  position: sticky; top: 0; z-index: 40;
  height: var(--topbar-alt);
  display: flex; align-items: center; justify-content: flex-end; gap: .75rem;
  padding: 0 2rem;
  background: #ffffff;
  border-bottom: 1px solid var(--g-200);
  box-shadow: var(--sombra-sm);
}
.topbar__botao {
  display: inline-flex; align-items: center; gap: .5rem;
  padding: .375rem .75rem;
  border: 1px solid var(--g-200); border-radius: var(--raio-btn-peq);
  background: #fff; cursor: pointer;
  font-size: .875rem; font-weight: 500; color: var(--g-700);
}
.topbar__botao:hover { background: var(--g-100); }
.topbar__icone {
  position: relative; padding: .5rem; border: 0; background: transparent;
  border-radius: var(--raio-btn-peq); color: var(--g-600); cursor: pointer; line-height: 0;
}
.topbar__icone:hover { background: var(--g-100); }
.topbar__icone .contador { position: absolute; top: -2px; right: -2px; margin: 0; }

/* Area de conteudo */
.conteudo { padding-left: var(--sidebar-larg); }
.conteudo--compacto { padding-left: var(--sidebar-larg-compacta); }
.conteudo main { padding: 2rem; }
.conteudo main > .container { max-width: var(--conteudo-max); margin: 0 auto; }

/* "Voltar ao menu <Secao>" — barra fina acima do conteudo */
.voltar-menu {
  display: inline-flex; align-items: center; gap: .375rem;
  margin-bottom: 1rem; padding: .375rem .625rem;
  border-radius: var(--raio-btn-peq);
  font-size: .875rem; font-weight: 500; color: var(--g-600); text-decoration: none;
}
.voltar-menu:hover { background: var(--g-100); color: var(--p-700); }

/* =========================================================================
   2. CABECALHO DE PAGINA
   ========================================================================= */

.pagina__cabecalho {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between;
  gap: .75rem; margin-bottom: 1rem;
}
.pagina__titulo {
  display: flex; align-items: center; gap: .5rem;
  font-size: 1.25rem; font-weight: 600; color: var(--s-800);
}
.pagina__titulo svg { width: 1.25rem; height: 1.25rem; color: var(--acento); }
.pagina__subtitulo { margin: .25rem 0 0; font-size: .875rem; color: var(--s-500); }
/* "?" do manual */
.ajuda-manual {
  display: inline-flex; align-items: center; justify-content: center;
  width: 1.5rem; height: 1.5rem; margin-left: .375rem;
  border-radius: 9999px; color: var(--g-400); text-decoration: none;
  transition: background-color .2s, color .2s;
}
.ajuda-manual:hover { background: var(--p-50); color: var(--p-700); }

/* =========================================================================
   3. BOTOES
   ========================================================================= */

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: .5rem;
  padding: .5rem 1rem;
  border: 1px solid transparent; border-radius: var(--raio-md);
  font-family: inherit; font-size: .875rem; font-weight: 500; line-height: 1.25rem;
  cursor: pointer; text-decoration: none;
  transition: color .2s, background-color .2s, border-color .2s, filter .2s, box-shadow .2s;
}
.btn:focus-visible { outline: 2px solid var(--p-500); outline-offset: 2px; }
.btn:disabled { opacity: .5; cursor: not-allowed; }
.btn svg { width: 1rem; height: 1rem; }
.btn--sm { padding: .375rem .75rem; font-size: .8125rem; gap: .375rem; }
.btn--lg { padding: .625rem 1rem;  font-size: .9375rem; }

.btn--primario {
  color: #ffffff;
  background-image: var(--marca-gradiente);
}
.btn--primario:hover { filter: brightness(1.07); box-shadow: var(--sombra-marca); }

.btn--secundario {
  color: #ffffff;
  background-color: var(--marca-secundaria);
  border-color: color-mix(in srgb, var(--marca-secundaria) 50%, #000 15%);
}
.btn--secundario:hover { filter: brightness(1.08); }

.btn--outline {
  color: var(--p-700);
  background: transparent;
  border-color: var(--marca-primaria);
}
.btn--outline:hover { background: var(--p-50); }

.btn--ghost {
  color: var(--g-700); background: transparent; border-color: transparent;
}
.btn--ghost:hover { background: var(--g-100); border-color: var(--borda); }

.btn--perigo { color: #fff; background: var(--erro); }
.btn--perigo:hover { background: var(--erro-600); }

/* =========================================================================
   4. TABELA DE LISTAGEM
   ========================================================================= */

.tabela-wrap {
  border: 1px solid var(--g-200); border-radius: var(--raio-sm);
  background: #ffffff; box-shadow: var(--sombra-sm);
  overflow-x: auto;
}
.tabela { width: 100%; min-width: 100%; border-collapse: collapse; }

.tabela thead { background: var(--g-50); }
.tabela th {
  padding: .75rem 1rem;
  text-align: left; white-space: nowrap;
  font-size: .75rem; font-weight: 600; line-height: 1rem;
  text-transform: uppercase; letter-spacing: .025em;
  color: var(--g-500);
  border-bottom: 1px solid var(--g-200);
}
.tabela th button {           /* cabecalho ordenavel */
  display: inline-flex; align-items: center; gap: .25rem;
  border: 0; background: transparent; cursor: pointer;
  font: inherit; text-transform: inherit; letter-spacing: inherit; color: inherit;
}
.tabela th button:hover { color: var(--g-700); }
.tabela th button svg { width: .875rem; height: .875rem; }

.tabela tbody tr { border-top: 1px solid var(--g-100); }
.tabela tbody tr:hover { background: var(--g-50); }
.tabela tbody tr.clicavel { cursor: pointer; }
/* Linha em atraso (fila da Ouvidoria) */
.tabela tbody tr.atrasada { background: rgb(254 242 242 / 0.40); }
.tabela tbody tr.atrasada:hover { background: #fef2f2; }

.tabela td {
  padding: .75rem 1rem;
  font-size: .875rem; line-height: 1.25rem; color: var(--g-700);
  vertical-align: top;
}
.tabela td.mono { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; color: var(--s-700); white-space: nowrap; }
.tabela td.suave { color: var(--s-600); }
.tabela .celula-titulo { font-size: .875rem; color: var(--s-800); }
.tabela .celula-sub {
  font-size: .75rem; color: var(--s-500);
  max-width: 20rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.tabela__vazio, .tabela__carregando {
  padding: 2rem 1rem; text-align: center; font-size: .875rem; color: var(--g-500);
}

/* =========================================================================
   5. CARD / BLOCO / KPI
   ========================================================================= */

.card {
  background: var(--superficie);
  border: 1px solid var(--borda);
  border-radius: var(--raio-lg);
  box-shadow: var(--sombra-sm);
}
.card--hover { transition: box-shadow .2s, border-color .2s; }
.card--hover:hover { box-shadow: var(--sombra-lg); border-color: var(--p-300); }

/* Bloco padrao das telas de Ouvidoria */
.bloco {
  background: #ffffff;
  border: 1px solid var(--s-200);
  border-radius: var(--raio-xl);
  box-shadow: var(--sombra-sm);
  padding: 1rem;
}
.bloco__titulo {
  margin: 0 0 .5rem; font-size: .875rem; font-weight: 600; color: var(--s-700);
}
.bloco--destaque { padding: 1.25rem; }

/* Cartao de indicador (KPI) */
.kpis { display: grid; gap: .75rem; grid-template-columns: repeat(6, minmax(0, 1fr)); }
@media (max-width: 1280px) { .kpis { grid-template-columns: repeat(3, minmax(0,1fr)); } }
@media (max-width: 768px)  { .kpis { grid-template-columns: repeat(2, minmax(0,1fr)); } }
@media (max-width: 520px)  { .kpis { grid-template-columns: 1fr; } }

.kpi {
  background: #fff; border: 1px solid var(--s-200);
  border-radius: var(--raio-xl); box-shadow: var(--sombra-sm); padding: 1rem;
}
.kpi__rotulo {
  margin: 0; font-size: .75rem; font-weight: 500;
  text-transform: uppercase; letter-spacing: .025em; color: var(--s-500);
}
.kpi__valor {
  margin: .25rem 0 0; font-size: 1.5rem; font-weight: 600;
  font-variant-numeric: tabular-nums; color: var(--s-900);
}
.kpi__valor--bom  { color: #15803d; }
.kpi__valor--ruim { color: #b91c1c; }
.kpi__detalhe { margin: .125rem 0 0; font-size: .75rem; color: var(--s-500); }

/* Caixa de icone dos cards do hub de menu */
.icon-box {
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
  padding: .5rem; border-radius: var(--raio-md);
  background: var(--p-100); color: var(--p-700);
}

/* =========================================================================
   6. CHIP / BADGE
   ========================================================================= */

.chip {
  display: inline-flex; align-items: center; gap: .25rem;
  padding: .125rem .5rem;
  border-radius: 9999px;
  font-size: .75rem; font-weight: 500; line-height: 1rem;
  white-space: nowrap;
  box-shadow: inset 0 0 0 1px var(--chip-anel, transparent);
  background: var(--chip-bg, var(--s-100));
  color: var(--chip-fg, var(--s-700));
}
.chip svg { width: .75rem; height: .75rem; }

/* --- Status da manifestacao --- */
.chip--registrada        { --chip-bg:#f1f5f9; --chip-fg:#334155; --chip-anel:rgb(71 85 105 / .2); }
.chip--triagem           { --chip-bg:#f0f9ff; --chip-fg:#0369a1; --chip-anel:rgb(2 132 199 / .2); }
.chip--encaminhada       { --chip-bg:#eff6ff; --chip-fg:#1d4ed8; --chip-anel:rgb(37 99 235 / .2); }
.chip--complementacao    { --chip-bg:#fffbeb; --chip-fg:#b45309; --chip-anel:rgb(217 119 6 / .2); }
.chip--respondida-area   { --chip-bg:#eef2ff; --chip-fg:#4338ca; --chip-anel:rgb(79 70 229 / .2); }
.chip--validacao         { --chip-bg:#f5f3ff; --chip-fg:#6d28d9; --chip-anel:rgb(124 58 237 / .2); }
.chip--respondida        { --chip-bg:#f0fdf4; --chip-fg:#15803d; --chip-anel:rgb(22 163 74 / .2); }
.chip--recurso           { --chip-bg:#fff7ed; --chip-fg:#c2410c; --chip-anel:rgb(234 88 12 / .2); }
.chip--concluida         { --chip-bg:#ecfdf5; --chip-fg:#065f46; --chip-anel:rgb(5 150 105 / .2); }
.chip--arquivada         { --chip-bg:#f4f4f5; --chip-fg:#52525b; --chip-anel:rgb(113 113 122 / .2); }
.chip--outro-orgao       { --chip-bg:#f5f5f4; --chip-fg:#44403c; --chip-anel:rgb(120 113 108 / .2); }

/* --- Tipo da manifestacao --- */
.chip--solicitacao { --chip-bg:#eff6ff; --chip-fg:#1d4ed8; --chip-anel:rgb(37 99 235 / .2); }
.chip--reclamacao  { --chip-bg:#fffbeb; --chip-fg:#92400e; --chip-anel:rgb(217 119 6 / .2); }
.chip--denuncia    { --chip-bg:#fef2f2; --chip-fg:#b91c1c; --chip-anel:rgb(220 38 38 / .2); }
.chip--sugestao    { --chip-bg:#f0fdfa; --chip-fg:#0f766e; --chip-anel:rgb(13 148 136 / .2); }
.chip--elogio      { --chip-bg:#f0fdf4; --chip-fg:#15803d; --chip-anel:rgb(22 163 74 / .2); }
.chip--informacao  { --chip-bg:#f1f5f9; --chip-fg:#334155; --chip-anel:rgb(71 85 105 / .2); }

/* --- Prioridade --- */
.chip--normal  { --chip-bg:#f1f5f9; --chip-fg:#334155; --chip-anel:rgb(71 85 105 / .2); }
.chip--alta    { --chip-bg:#fff7ed; --chip-fg:#c2410c; --chip-anel:rgb(234 88 12 / .2); }
.chip--urgente { --chip-bg:#fef2f2; --chip-fg:#b91c1c; --chip-anel:rgb(220 38 38 / .2); }

/* --- Identificacao (so aparece quando nao e identificada) --- */
.chip--sigilo { --chip-bg:#faf5ff; --chip-fg:#7e22ce; --chip-anel:rgb(147 51 234 / .2); }

/* --- Prazo --- */
.chip--prazo-ok       { --chip-bg:#f0fdf4; --chip-fg:#15803d; --chip-anel:rgb(22 163 74 / .2); }
.chip--prazo-perto    { --chip-bg:#fffbeb; --chip-fg:#92400e; --chip-anel:rgb(217 119 6 / .2); }
.chip--prazo-atrasado { --chip-bg:#fef2f2; --chip-fg:#b91c1c; --chip-anel:rgb(220 38 38 / .2); }
.chip--prazo-encerrado{ --chip-bg:#f1f5f9; --chip-fg:#475569; --chip-anel:rgb(100 116 139 / .2); }
.chip__rotulo { font-weight: 400; opacity: .8; }

/* Badge generico (.badge do painel) */
.badge {
  display: inline-flex; align-items: center; gap: .25rem;
  padding: .125rem .625rem; border-radius: 9999px;
  font-size: .75rem; font-weight: 500;
}
.badge--primario { background: var(--p-100);  color: var(--p-700); }
.badge--sucesso  { background: #d1fae5;       color: #047857; }
.badge--aviso    { background: #fef3c7;       color: #b45309; }
.badge--erro     { background: #fee2e2;       color: #b91c1c; }
.badge--cinza    { background: var(--g-100);  color: var(--g-700); }

/* =========================================================================
   7. INPUT, SELECT, CAMPO
   ========================================================================= */

.campo { display: flex; flex-direction: column; }
.label {
  display: inline-flex; align-items: center; gap: .25rem;
  margin-bottom: .25rem;
  font-size: .875rem; font-weight: 500; color: var(--texto-suave);
}
.label .obrigatorio { color: var(--erro); }

.input, .select, .textarea {
  width: 100%;
  padding: .5rem 1rem;
  border: 1px solid var(--borda);
  border-radius: var(--raio-md);
  background-color: var(--superficie);
  color: var(--texto);
  font-family: inherit; font-size: .875rem; line-height: 1.25rem;
  transition: border-color .2s, box-shadow .2s;
}
.input::placeholder, .textarea::placeholder { color: var(--g-400); }
.input:focus, .select:focus, .textarea:focus {
  outline: none;
  border-color: var(--p-500);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--p-500) 20%, transparent);
}
.input:disabled, .select:disabled { background: var(--g-100); cursor: not-allowed; }

.select {
  appearance: none;
  padding-right: 2.25rem;
  background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='16' height='16' viewBox='0 0 24 24' fill='none' stroke='%2371717a' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='m6 9 6 6 6-6'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right .75rem center;
}
.textarea { min-height: 7rem; resize: vertical; }

.campo__dica { margin-top: .25rem; font-size: .75rem; color: var(--g-500); }
.campo__erro { margin-top: .25rem; font-size: .75rem; color: var(--erro-600); }

/* Linha de filtros da fila (larguras reais das telas de Ouvidoria) */
.filtros { display: flex; flex-wrap: wrap; align-items: flex-end; gap: .75rem; margin-bottom: 1rem; }
.filtros .f-busca      { width: 16rem; }
.filtros .f-tipo       { width: 11rem; }
.filtros .f-prioridade { width: 10rem; }
.filtros .f-unidade    { width: 14rem; }
.filtros .f-ponto      { width: 16rem; }

/* =========================================================================
   8. ABAS
   ========================================================================= */

.abas { border-bottom: 1px solid var(--g-200); }
.abas__lista { display: flex; flex-wrap: wrap; gap: .25rem; margin-bottom: -1px; }
.aba {
  padding: .5rem 1rem;
  border: 0; border-bottom: 2px solid transparent; background: transparent;
  font-family: inherit; font-size: .875rem; font-weight: 500;
  color: var(--g-500); cursor: pointer; white-space: nowrap;
  transition: color .2s, border-color .2s;
}
.aba:hover { color: var(--g-700); border-bottom-color: var(--g-300); }
.aba--ativa { color: var(--acento-escuro); border-bottom-color: var(--acento); }
.aba__badge {
  margin-left: .5rem; padding: .125rem .5rem;
  border-radius: 9999px; background: var(--g-100); color: var(--g-700);
  font-size: .75rem;
}
.abas__painel { padding-top: 1rem; }

/* =========================================================================
   9. PAGINACAO
   ========================================================================= */

.paginacao {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between;
  gap: .75rem; margin-top: .75rem;
  font-size: .875rem; color: var(--s-600);
}
.paginacao__tamanho { display: flex; align-items: center; gap: .5rem; }
.paginacao__tamanho select {
  padding: .25rem .5rem;
  border: 1px solid var(--s-300); border-radius: var(--raio-btn-peq);
  background: #fff; color: var(--s-800); font: inherit; font-size: .875rem;
}
.paginacao__tamanho select:focus { outline: none; border-color: var(--acento-escuro); }
.paginacao__intervalo { font-variant-numeric: tabular-nums; }
.paginacao__nav { display: flex; align-items: center; gap: .25rem; }
.pag-btn {
  display: inline-flex; align-items: center; justify-content: center;
  height: 2rem; min-width: 2rem; padding: 0 .5rem;
  border: 1px solid var(--s-300); border-radius: var(--raio-btn-peq);
  background: #ffffff; color: inherit;
  font: inherit; font-size: .875rem; font-variant-numeric: tabular-nums;
  cursor: pointer; transition: background-color .15s, border-color .15s;
}
.pag-btn:hover:not(:disabled) { background: var(--s-50); }
.pag-btn:disabled { opacity: .4; cursor: not-allowed; }
.pag-btn--atual {
  border-color: var(--acento-escuro); background: var(--acento-escuro);
  color: #ffffff; font-weight: 600;
}
.paginacao__reticencias { padding: 0 .25rem; color: var(--s-400); }

/* =========================================================================
   10. AVISOS INLINE (usados nas telas de Ouvidoria)
   ========================================================================= */

.aviso {
  display: flex; align-items: flex-start; gap: .5rem;
  padding: .5rem .75rem; border-radius: var(--raio-sm);
  font-size: .875rem;
}
.aviso--erro   { border: 1px solid #fecaca; background: #fef2f2; color: #b91c1c; }
.aviso--ambar  { border: 1px solid #fde68a; background: #fffbeb; color: #92400e; }
.aviso--verde  { border: 1px solid #bbf7d0; background: #f0fdf4; color: #166534; }
.aviso svg { width: 1rem; height: 1rem; flex-shrink: 0; margin-top: .125rem; }

/* Grade de 3 colunas da tela de detalhe (2/3 relato + 1/3 lateral) */
.detalhe-grid { display: grid; gap: 1.25rem; grid-template-columns: 2fr 1fr; }
@media (max-width: 1024px) { .detalhe-grid { grid-template-columns: 1fr; } }
.pilha { display: flex; flex-direction: column; gap: 1.25rem; }
